// Blink — Arduino Uno R3
const int LED_PIN = LED_BUILTIN;


void setup() {
  pinMode(LED_PIN, OUTPUT);
}


void loop() {
  digitalWrite(LED_PIN, HIGH);
  delay(1000);
  digitalWrite(LED_PIN, LOW);
  delay(1000);
}

// Button — connect a pushbutton between pin 2 and GND
const int BUTTON_PIN = 2;
const int LED_PIN = LED_BUILTIN;


void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
}


void loop() {
  bool pressed = digitalRead(BUTTON_PIN) == LOW;
  digitalWrite(LED_PIN, pressed ? HIGH : LOW);
}

// Potentiometer: outer pins to 5V/GND, middle pin to A0.
void setup() { Serial.begin(9600); }
void loop() {
  Serial.println(analogRead(A0));
  delay(50);
}

void setup() { Serial.begin(9600); }
void loop() {
  Serial.print(F("time:"));
  Serial.println(millis() / 1000.0, 1);
  delay(100);
}

// Button between D2 and GND. Press when the onboard LED turns on.
enum GameState { WAIT_RELEASE, WAIT_SIGNAL, WAIT_PRESS };
GameState state = WAIT_RELEASE;
unsigned long signalAt = 0, startedAt = 0;
void setup() {
  pinMode(2, INPUT_PULLUP); pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600); randomSeed(analogRead(A0));
  Serial.println(F("Release the button to begin."));
}
void loop() {
  bool pressed = digitalRead(2) == LOW;
  unsigned long now = millis();
  if (state == WAIT_RELEASE && !pressed) {
    signalAt = now + random(1500, 4500); state = WAIT_SIGNAL;
    Serial.println(F("Wait for the LED..."));
  } else if (state == WAIT_SIGNAL && pressed) {
    Serial.println(F("Too soon! Release to retry.")); state = WAIT_RELEASE;
  } else if (state == WAIT_SIGNAL && (long)(now - signalAt) >= 0) {
    digitalWrite(LED_BUILTIN, HIGH); startedAt = now; state = WAIT_PRESS;
  } else if (state == WAIT_PRESS && pressed) {
    digitalWrite(LED_BUILTIN, LOW);
    Serial.print(F("Reaction ms: ")); Serial.println(now - startedAt);
    state = WAIT_RELEASE; delay(30);
  }
}

#include <Servo.h>


Servo arm;


void setup() {
  arm.attach(9);
}


void loop() {
  arm.write(0);
  delay(800);
  arm.write(90);
  delay(800);
  arm.write(180);
  delay(800);
}

#include <Servo.h>
Servo arm;
void setup() { arm.attach(9); }
void loop() {
  for (int angle = 0; angle <= 180; angle++) { arm.write(angle); delay(15); }
  for (int angle = 180; angle >= 0; angle--) { arm.write(angle); delay(15); }
}

#include <Wire.h>
void setup() { Wire.begin(); Serial.begin(9600); }
void loop() {
  Serial.println(F("Scanning I2C: SDA=A4, SCL=A5"));
  for (byte address = 1; address < 127; address++) {
    Wire.beginTransmission(address);
    if (Wire.endTransmission() == 0) {
      Serial.print(F("Found 0x")); Serial.println(address, HEX);
    }
  }
  delay(3000);
}

#include <SPI.h>
void setup() { pinMode(10, OUTPUT); digitalWrite(10, HIGH); SPI.begin(); Serial.begin(9600); }
void loop() {
  SPI.beginTransaction(SPISettings(1000000, MSBFIRST, SPI_MODE0));
  digitalWrite(10, LOW);
  byte response = SPI.transfer(0x55);
  digitalWrite(10, HIGH);
  SPI.endTransaction();
  Serial.println(response, HEX);
  delay(1000);
}

#include <EEPROM.h>
void setup() {
  Serial.begin(9600);
  // update() writes only when the value changes. Avoid repeated EEPROM writes.
  EEPROM.update(0, 42);
  Serial.print(F("Stored value: ")); Serial.println(EEPROM.read(0));
  int calibration = 1234;
  EEPROM.put(4, calibration);
  int restored = 0;
  EEPROM.get(4, restored);
  Serial.println(restored);
}
void loop() {}

#include <SoftwareSerial.h>
SoftwareSerial device(10, 11); // RX, TX; connect to a compatible serial device.
void setup() { Serial.begin(9600); device.begin(9600); }
void loop() {
  if (device.available()) Serial.write(device.read());
  if (Serial.available()) device.write(Serial.read());
}

#include <LiquidCrystal.h>
LiquidCrystal lcd(12, 11, 5, 4, 3, 2); // RS, E, D4, D5, D6, D7
void setup() { lcd.begin(16, 2); lcd.print("Hello, maker!"); }
void loop() { lcd.setCursor(0, 1); lcd.print(millis() / 1000); }

#include <DHT.h>
DHT sensor(2, DHT22); // Change DHT22 to DHT11 for that sensor.
void setup() { Serial.begin(9600); sensor.begin(); }
void loop() {
  delay(2000);
  float temperature = sensor.readTemperature();
  float humidity = sensor.readHumidity();
  if (isnan(temperature) || isnan(humidity)) { Serial.println(F("Check DHT wiring")); return; }
  Serial.print(temperature); Serial.print(F(" C, "));
  Serial.print(humidity); Serial.println(F(" % RH"));
}

#include <Adafruit_Sensor.h>
#include <DHT_U.h>
DHT_Unified sensor(2, DHT22);
void setup() {
  Serial.begin(9600); sensor.begin();
  sensor.temperature().printSensorDetails();
  sensor_t metadata;
  sensor.temperature().getSensor(&metadata);
  Serial.println(metadata.name);
}
void loop() {
  sensors_event_t event;
  sensor.temperature().getEvent(&event);
  if (!isnan(event.temperature)) Serial.println(event.temperature);
  delay(2000);
}

#include <Adafruit_GFX.h>
GFXcanvas1 canvas(16, 16);
void setup() {
  Serial.begin(9600);
  canvas.fillScreen(0); canvas.drawLine(0, 0, 15, 15, 1);
  canvas.drawCircle(8, 8, 5, 1); canvas.setCursor(0, 0); canvas.print("A");
  Serial.println(canvas.getPixel(8, 8));
  Serial.println(canvas.getBuffer()[0], HEX);
}
void loop() {}

#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 display(128, 64, &Wire, -1);
void setup() {
  // Uno: SDA=A4, SCL=A5. Verify your display's I2C address.
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { for (;;) {} }
  display.clearDisplay(); display.setTextSize(1); display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0); display.println(F("Hello, maker!"));
  display.drawRect(0, 20, 100, 30, SSD1306_WHITE); display.display();
}
void loop() {}

#include <Adafruit_I2CDevice.h>
#include <Adafruit_BusIO_Register.h>
Adafruit_I2CDevice device(0x40, &Wire);
Adafruit_BusIO_Register deviceRegister(&device, 0x00, 1);
void setup() { Serial.begin(9600); Serial.println(device.begin()); }
void loop() {
  // Use the address and register map specified by your sensor's datasheet.
  Serial.println(deviceRegister.read(), HEX);
  delay(1000);
}

#include <Adafruit_NeoPixel.h>
Adafruit_NeoPixel pixels(8, 6, NEO_GRB + NEO_KHZ800);
void setup() { pixels.begin(); pixels.setBrightness(20); }
void loop() {
  for (uint16_t i = 0; i < pixels.numPixels(); i++) {
    pixels.clear(); pixels.setPixelColor(i, pixels.Color(0, 80, 180));
    pixels.show(); delay(120);
  }
}

#include <NewPing.h>
NewPing sonar(9, 10, 200); // trigger, echo, maximum cm
void setup() { Serial.begin(9600); }
void loop() {
  unsigned int duration = sonar.ping_median(3);
  Serial.print(sonar.convert_cm(duration)); Serial.println(F(" cm"));
  delay(100);
}

#include <IRremote.hpp>
void setup() { Serial.begin(9600); IrReceiver.begin(2, DISABLE_LED_FEEDBACK); }
void loop() {
  if (IrReceiver.decode()) {
    IrReceiver.printIRResultShort(&Serial);
    Serial.println();
    IrReceiver.resume();
  }
}

#include <Keypad.h>
const byte ROWS = 4, COLS = 3;
char keys[ROWS][COLS] = {{'1','2','3'}, {'4','5','6'}, {'7','8','9'}, {'*','0','#'}};
byte rowPins[ROWS] = {9, 8, 7, 6};
byte colPins[COLS] = {5, 4, 3};
Keypad keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);
void setup() { Serial.begin(9600); }
void loop() { char key = keypad.getKey(); if (key) Serial.println(key); }

#include <AccelStepper.h>
// Use a suitable motor driver; do not connect motor windings to Uno pins.
AccelStepper motor(AccelStepper::DRIVER, 3, 2); // step, direction
void setup() { motor.setMaxSpeed(400); motor.setAcceleration(100); motor.moveTo(200); }
void loop() {
  if (motor.distanceToGo() == 0) motor.moveTo(-motor.currentPosition());
  motor.run();
}

#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2); // johnrickman 1.1.2 API; scan for your address.
void setup() { lcd.init(); lcd.backlight(); lcd.setCursor(0, 0); lcd.print("Hello, maker!"); }
void loop() { lcd.setCursor(0, 1); lcd.print(millis() / 1000); }

// LED + 220 ohm resistor on PWM pin 9 to GND.
int brightness = 0;
int stepSize = 5;
void setup() { pinMode(9, OUTPUT); }
void loop() {
  analogWrite(9, brightness);
  brightness += stepSize;
  if (brightness <= 0 || brightness >= 255) stepSize = -stepSize;
  delay(30);
}

// HC-SR04: TRIG to pin 9, ECHO to pin 10
const int TRIG_PIN = 9;
const int ECHO_PIN = 10;


void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  Serial.begin(9600);
}


void loop() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);


  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  float centimeters = duration * 0.0343 / 2.0;
  Serial.print("Distance: ");
  Serial.print(centimeters);
  Serial.println(" cm");
  delay(250);
}

// Voltage divider: 5V -> LDR -> A0 -> 10k resistor -> GND.
void setup() { Serial.begin(9600); }
void loop() {
  Serial.print(F("light:"));
  Serial.println(analogRead(A0));
  delay(100);
}

#include <Servo.h>
// Servo signal: D9. Potentiometer middle pin: A0; outer pins: 5V/GND.
Servo arm;
void setup() { arm.attach(9); }
void loop() {
  int angle = map(analogRead(A0), 0, 1023, 0, 180);
  arm.write(constrain(angle, 0, 180));
  delay(15);
}

#include <Adafruit_SSD1306.h>
#include <DHT.h>
Adafruit_SSD1306 display(128, 64, &Wire, -1);
DHT sensor(2, DHT22);
void setup() {
  sensor.begin();
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { for (;;) {} }
  display.setTextColor(SSD1306_WHITE); display.setTextSize(1);
}
void loop() {
  delay(2000);
  float temperature = sensor.readTemperature();
  float humidity = sensor.readHumidity();
  display.clearDisplay(); display.setCursor(0, 0);
  if (isnan(temperature) || isnan(humidity)) display.println(F("Check DHT wiring"));
  else {
    display.print(F("Temp: ")); display.print(temperature, 1); display.println(F(" C"));
    display.print(F("Humidity: ")); display.print(humidity, 1); display.println(F(" %"));
  }
  display.display();
}

// Red D8, yellow D9, green D10; each LED needs a 220 ohm resistor.
const int RED = 8, YELLOW = 9, GREEN = 10;
void setup() {
  pinMode(RED, OUTPUT); pinMode(YELLOW, OUTPUT); pinMode(GREEN, OUTPUT);
}
void loop() {
  digitalWrite(RED, HIGH); delay(3000); digitalWrite(RED, LOW);
  digitalWrite(GREEN, HIGH); delay(3000); digitalWrite(GREEN, LOW);
  digitalWrite(YELLOW, HIGH); delay(1000); digitalWrite(YELLOW, LOW);
}

// HC-SR04 TRIG D9, ECHO D10. Passive piezo on D3 and GND.
void setup() {
  pinMode(9, OUTPUT); pinMode(10, INPUT); pinMode(3, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  digitalWrite(9, LOW); delayMicroseconds(2);
  digitalWrite(9, HIGH); delayMicroseconds(10); digitalWrite(9, LOW);
  unsigned long echo = pulseIn(10, HIGH, 30000);
  float cm = echo * 0.0343 / 2;
  Serial.print(F("distance:")); Serial.println(cm);
  if (echo > 0 && cm < 50) { tone(3, 1000, 60); delay((int)constrain(cm * 8, 80, 400)); }
  else { noTone(3); delay(200); }
}

#include <Servo.h>
// Small model door: servo signal D6; HC-SR04 TRIG D9, ECHO D10.
Servo door;
unsigned long lastSeen = 0;
bool opened = false;
void setup() {
  door.attach(6); door.write(0); pinMode(9, OUTPUT); pinMode(10, INPUT);
}
void loop() {
  digitalWrite(9, LOW); delayMicroseconds(2);
  digitalWrite(9, HIGH); delayMicroseconds(10); digitalWrite(9, LOW);
  unsigned long echo = pulseIn(10, HIGH, 30000);
  if (echo > 0 && echo < 1160) { lastSeen = millis(); opened = true; door.write(90); }
  if (opened && millis() - lastSeen > 3000) { door.write(0); opened = false; }
  delay(80);
}

// PIR sensor OUT to D2; passive piezo to D3; common GND.
// Allow your PIR module to settle after power-on.
void setup() {
  pinMode(2, INPUT); pinMode(LED_BUILTIN, OUTPUT); Serial.begin(9600);
}
void loop() {
  bool motion = digitalRead(2) == HIGH;
  digitalWrite(LED_BUILTIN, motion);
  if (motion) tone(3, 880); else noTone(3);
  Serial.print(F("motion:")); Serial.println(motion ? 1 : 0);
  delay(100);
}

