volatile unsigned long edges = 0;
void changed() { edges++; }
void setup() {
 Serial.begin(9600); pinMode(2, INPUT_PULLUP);
 attachInterrupt(digitalPinToInterrupt(2), changed, FALLING);
}
void loop() {
 noInterrupts(); unsigned long n = edges; interrupts();
 Serial.println(n); delay(100);
 if (n > 100) detachInterrupt(digitalPinToInterrupt(2));
}
